                    <a href="/offwork/eleveight#{{ product.category }}" class="btn-ghost">К линейке</a>
                </div>
            </div>
        </div>

        {% if product.body_paragraphs %}
        <div class="product-description-panel elv-body">
            {% for para in product.body_paragraphs %}
