            <a href="tel:+79383480165" class="btn-primary">+7 (938) 348-01-65</a>
            {% if product.official %}
            <a href="{{ product.official }}" class="btn-ghost" target="_blank" rel="noopener">Страница производителя</a>
            {% endif %}
        </div>
    </div>
</section>

{% if related %}
<section class="section bg-paper">
    <div class="container">
        <h2 class="section-title">Ещё в этой линейке</h2>
        <div class="catalog-list">
            {% for item in related %}
            <article class="catalog-row elv-row">
                <a href="/offwork/eleveight/{{ item.slug }}" class="catalog-row-link">
                    <span class="catalog-row-photo">
                        {% if item.image %}<img src="{{ item.image }}" alt="">{% endif %}
                    </span>
                    <span class="catalog-row-main">
                        <span class="catalog-row-top">
                            <strong class="catalog-row-name">{{ item.name }}</strong>
                        </span>
                        <span class="catalog-row-desc">{{ item.short_desc }}</span>
                    </span>
                </a>
                <div class="catalog-row-actions">
                    <a href="/offwork/eleveight/{{ item.slug }}" class="catalog-row-more">→</a>
                </div>
            </article>
            {% endfor %}
        </div>
    </div>
</section>
{% endif %}
{% endblock %}

